package vn.boardinghub.modules.room;import vn.boardinghub.shared.api.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import org.springframework.data.domain.Page;
@RestController@RequestMapping("/api/v1/rooms")public class RoomController{private final RoomService s;public RoomController(RoomService s){this.s=s;}@GetMapping public ApiResponse<Page<RoomDtos.Response>> list(@RequestParam(required=false)Long propertyId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid pagination");return ApiResponse.ok("Rooms",s.list(propertyId,page,size));}@GetMapping("/{id}")public ApiResponse<RoomDtos.Response> get(@PathVariable Long id){return ApiResponse.ok("Room",s.get(id));}@PostMapping public ApiResponse<RoomDtos.Response> create(@Valid@RequestBody RoomDtos.Request r){return ApiResponse.ok("Room created",s.create(r));}@PutMapping("/{id}")public ApiResponse<RoomDtos.Response> update(@PathVariable Long id,@Valid@RequestBody RoomDtos.Request r){return ApiResponse.ok("Room updated",s.update(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void> delete(@PathVariable Long id){s.delete(id);return ApiResponse.ok("Room deleted",null);}}
